#include <stdint.h>
#include <stm32f4xx.h>
#include <stm32f411xe.h>
void init_hardware(void);
int main(void)
{
    init_hardware();   
    /* Loop forever */
	while(1);
        if (SysTick->CTRL & SysTick_CTRL_COUNTFLAG_Msk) {
            GPIOB->ODR ^= GPIO_ODR_OD8; // Toggle PB8 (Red LED)
            GPIOB->ODR ^= GPIO_ODR_OD9; // Toggle PB9 (Green LED)
            GPIOB->ODR ^= GPIO_ODR_OD6; // Toggle PB6 (Yellow LED)
        }
}

void init_hardware(void)
{
    /* Enable GPIOB clock */
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN;
    //ROJO

    /* Set PB8 as output */

    GPIOB->MODER &= ~(GPIO_MODER_MODE8); // Clear mode bits for PB8
    GPIOB->MODER |= (GPIO_MODER_MODE8_0);  // Set PB8 to output mode (01)

    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT8); // Set PB8 to push-pull (0)

    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED8); // Clear speed bits for PB8
    GPIOB->OSPEEDR |= (GPIO_OSPEEDR_OSPEED8_1); // Set PB8 to high speed (11)

    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD8); // Clear pull-up/pull-down bits for PB8

    GPIOB->ODR &= ~(GPIO_ODR_OD8); // Set PB8 low (turn off LED)
    GPIOB->ODR |= GPIO_ODR_OD8; // Set PB8 high (turn on LED)

    //VERDE
    /* Set PA5 as output */
    GPIOB->MODER &= ~(GPIO_MODER_MODE9); // Clear mode bits for PA5
    GPIOB->MODER |= (GPIO_MODER_MODE9_0);  // Set PA5 to output mode (01)

    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT9); // Set PA5 to push-pull (0)

    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED9); // Clear speed bits for PA5
    GPIOB->OSPEEDR |= (GPIO_OSPEEDR_OSPEED9_1); // Set PA5 to high speed (11)

    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD9); // Clear pull-up/pull-down bits for PA5

    GPIOB->ODR &= ~(GPIO_ODR_OD9); // Set PA5 low (turn off LED)
    GPIOB->ODR |= GPIO_ODR_OD9; // Set PA5 high (turn on LED)

    //AMARILLO

    /* Set PA5 as output */
    GPIOB->MODER &= ~(GPIO_MODER_MODE6); // Clear mode bits for PA5
    GPIOB->MODER |= (GPIO_MODER_MODE6_0);  // Set PA5 to output mode (01)

    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT6); // Set PA5 to push-pull (0)

    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED6); // Clear speed bits for PA5
    GPIOB->OSPEEDR |= (GPIO_OSPEEDR_OSPEED6_1); // Set PA5 to high speed (11)

    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD6); // Clear pull-up/pull-down bits for PA5

    GPIOB->ODR &= ~(GPIO_ODR_OD6); // Set PA5 low (turn off LED)
    GPIOB->ODR |= GPIO_ODR_OD6; // Set PA5 high (turn on LED)

    SysTick->LOAD = 16000000 - 1; // Set reload value for 1 second delay (assuming 16 MHz clock)
    SysTick->VAL = 0; // Clear current value
    SysTick->CTRL |= SysTick_CTRL_CLKSOURCE_Msk; // Use processor clock
    SysTick->CTRL |= SysTick_CTRL_ENABLE_Msk; // Enable SysTick timer

}
